  "faq": {
    "title": "Frequently Asked Questions",
    "q1": "What are bio-fertilizers and how do they work?",
    "a1": "Bio-fertilizers contain living cells of beneficial microorganisms. When applied to seed or soil, they colonize the rhizosphere and make nutrients available to plants by fixing nitrogen, solubilizing phosphates, and mobilizing potash.",
    "q2": "How do I apply dextrose-based powder?",
    "a2": "Dextrose powders are highly water-soluble. They can be mixed with seeds for seed coating, dissolved in water for root dipping, or applied through drip irrigation systems at recommended dosages.",
    "q3": "Are bio-pesticides safe for earthworms and bees?",
    "a3": "Yes, our biological pest control range (like Beauveria and Verticillium) specifically targets insect pests and larvae on contact. They are completely safe for non-target organisms like earthworms and crop pollinators.",
    "q4": "Can I mix bio-fertilizers with chemical inputs?",
    "a4": "We strongly advise against mixing live bio-fertilizers directly with chemical bactericides or chemical fungicides, as they will kill the beneficial living microbes. Allow a gap of 7-10 days between chemical and biological applications."
  },
