  "aboutUsHeading": "About Our Company",
  "companyOverviewTag": "Overview",
  "companyOverviewTitle": "Bridging Biotechnology and Agriculture",
  "aboutText1": "BHARTI GREEN TECH is an Indian agricultural biotechnology company dedicated to building research-backed, high-efficacy crop feed and biological protection solutions. Based out of our registered office in Navi Mumbai and manufacturing units in Satara, Maharashtra, we formulate biological solutions that enrich the soil, stimulate seeds, and fortify foliage against fungal or pest stresses.",
  "aboutText2": "We operate with a farmer-first philosophy. Rather than relying on generic chemicals that damage soil carbon over time, our laboratory processes isolate specific microbial organisms, including Nitrogen-fixers, Phosphate solubilizers, and entomopathogenic fungi. These are refined into water-soluble dextrose carrier powders, stable liquid consortia, and slow-release granules for diverse crop requirements.",
  "whyTag": "Core Values",
  "valuesTitle": "The Principles We Stand By",
  "valuesSubtitle": "We formulate bio-solutions with maximum responsibility, ensuring safety for the environment, soil structure, and humans.",
