  "val1Desc": "Every batch is formulated based on documented microbiological principles, avoiding unverified yield claims.",
  "val2Title": "Farmer Empowerment",
  "val2Desc": "We supply clear application guidelines, dilutions, and precautions to help farmers achieve success.",
  "val3Title": "Eco-Responsibility",
  "val3Desc": "Products degrade naturally without chemical runoff, maintaining earthworm populations and groundwater safety.",
