  "faq": {
    "title": "अक्सर पूछे जाने वाले प्रश्नों",
    "q1": "जैव उर्वरक क्या हैं और वे कैसे काम करते हैं?",
    "a1": "जैव-उर्वरकों में लाभकारी सूक्ष्मजीवों की जीवित कोशिकाएँ होती हैं। जब बीज या मिट्टी पर लगाया जाता है, तो वे राइजोस्फीयर में बस जाते हैं और नाइट्रोजन स्थिर करके, फॉस्फेट को घुलनशील बनाकर और पोटाश जुटाकर पौधों को पोषक तत्व उपलब्ध कराते हैं।",
    "q2": "मैं डेक्सट्रोज़-आधारित पाउडर कैसे लगाऊं?",
    "a2": "डेक्सट्रोज़ पाउडर अत्यधिक पानी में घुलनशील होते हैं। उन्हें बीज कोटिंग के लिए बीजों के साथ मिलाया जा सकता है, जड़ों को डुबाने के लिए पानी में घोला जा सकता है, या अनुशंसित खुराक पर ड्रिप सिंचाई प्रणाली के माध्यम से लगाया जा सकता है।",
    "q3": "क्या जैव-कीटनाशक केंचुओं और मधुमक्खियों के लिए सुरक्षित हैं?",
    "a3": "हां, हमारी जैविक कीट नियंत्रण रेंज (जैसे ब्यूवेरिया और वर्टिसिलियम) विशेष रूप से संपर्क में आने वाले कीटों और लार्वा को लक्षित करती है। वे केंचुए और फसल परागणकों जैसे गैर-लक्षित जीवों के लिए पूरी तरह से सुरक्षित हैं।",
    "q4": "क्या मैं जैव-उर्वरकों को रासायनिक आदानों के साथ मिला सकता हूँ?",
    "a4": "हम जीवित जैव-उर्वरकों को सीधे रासायनिक जीवाणुनाशकों या रासायनिक कवकनाशी के साथ मिलाने के खिलाफ दृढ़ता से सलाह देते हैं, क्योंकि वे लाभकारी जीवित रोगाणुओं को मार देंगे। रासायनिक और जैविक अनुप्रयोगों के बीच 7-10 दिनों का अंतर रखें।"
  },
