  "aboutUsHeading": "हमारी कंपनी के बारे में",
  "companyOverviewTag": "सिंहावलोकन",
  "companyOverviewTitle": "जैव प्रौद्योगिकी और कृषि को जोड़ना",
  "aboutText1": "भारती ग्रीन टेक एक भारतीय कृषि जैव प्रौद्योगिकी कंपनी है जो अनुसंधान-समर्थित, उच्च दक्षता वाली फसल फ़ीड और जैविक सुरक्षा समाधान बनाने के लिए समर्पित है। नवी मुंबई में हमारे पंजीकृत कार्यालय और सतारा, महाराष्ट्र में विनिर्माण इकाइयों के आधार पर, हम जैविक समाधान तैयार करते हैं जो मिट्टी को समृद्ध करते हैं, बीजों को उत्तेजित करते हैं, और कवक या कीट तनाव के खिलाफ पत्ते को मजबूत करते हैं।",
  "aboutText2": "हम किसान-प्रथम दर्शन के साथ काम करते हैं। समय के साथ मिट्टी के कार्बन को नुकसान पहुंचाने वाले सामान्य रसायनों पर भरोसा करने के बजाय, हमारी प्रयोगशाला प्रक्रियाएँ नाइट्रोजन-फिक्सर्स, फॉस्फेट सॉल्यूबिलाइज़र और एंटोमोपैथोजेनिक कवक सहित विशिष्ट माइक्रोबियल जीवों को अलग करती हैं। इन्हें विभिन्न फसल आवश्यकताओं के लिए पानी में घुलनशील डेक्सट्रोज वाहक पाउडर, स्थिर तरल कंसोर्टिया और धीमी गति से निकलने वाले कणिकाओं में परिष्कृत किया जाता है।",
  "whyTag": "बुनियादी मूल्य",
  "valuesTitle": "जिन सिद्धांतों पर हम कायम हैं",
  "valuesSubtitle": "हम पर्यावरण, मिट्टी की संरचना और मनुष्यों के लिए सुरक्षा सुनिश्चित करते हुए अधिकतम जिम्मेदारी के साथ जैव-समाधान तैयार करते हैं।",
  "val1Title": "वैज्ञानिक प्रामाणिकता",
  "val1Desc": "असत्यापित उपज दावों से बचते हुए, प्रत्येक बैच को प्रलेखित सूक्ष्मजीवविज्ञानी सिद्धांतों के आधार पर तैयार किया जाता है।",
  "val2Title": "किसान सशक्तिकरण",
  "val2Desc": "हम किसानों को सफलता प्राप्त करने में मदद करने के लिए स्पष्ट अनुप्रयोग दिशानिर्देश, तनुकरण और सावधानियां प्रदान करते हैं।",
  "val3Title": "पर्यावरण के जिम्मेदारी",
  "val3Desc": "रासायनिक अपवाह के बिना उत्पाद प्राकृतिक रूप से नष्ट हो जाते हैं, जिससे केंचुओं की आबादी और भूजल सुरक्षा बनी रहती है।",
  "val4Title": "गुणवत्ता संगति",
  "val4Desc": "प्रत्येक पैकेज में उच्च बीजाणु व्यवहार्यता और कॉलोनी बनाने की संख्या सुनिश्चित करने के लिए सख्त अनुसंधान एवं विकास जांच की जाती है।",
  "infraTag": "हमारी सुविधाओं",
  "infraTitle": "अत्याधुनिक बुनियादी ढाँचा",
  "infraSubtitle": "हमारे कॉर्पोरेट निर्देशांक और विनिर्माण केंद्रों का विवरण जहां जैविक समाधान डिजाइन और पैक किए जाते हैं।",
