  "heroTitle": "स्वस्थ फसलों और बेहतर खेती के लिए उन्नत जैव प्रौद्योगिकी",
  "heroDesc": "मृदा स्वास्थ्य में सुधार, फसल वृद्धि में सहायता और किसानों को स्थायी उत्पादकता प्राप्त करने में मदद करने के लिए डिज़ाइन किए गए अनुसंधान-संचालित जैविक कृषि समाधान।",
  "watchVideoBtn": "उत्पाद वीडियो देखें",
  "introTag": "कंपनी के बारे में",
  "introTitle": "विज्ञान के साथ बढ़ रहा है. किसानों को सशक्त बनाना.",
  "introDesc": "भारती ग्रीन टेक उच्च गुणवत्ता वाले जैविक फसल इनपुट के निर्माण के लिए प्रतिबद्ध है। हम मृदा सुधार, फसल सुरक्षा और बीज शक्ति के लिए स्थिर, जैविक विकल्प प्रदान करने के लिए सूक्ष्म जीव विज्ञान में सक्रिय अनुसंधान को क्षेत्र-परीक्षण के साथ जोड़ते हैं।",
  "missionTitle": "हमारा विशेष कार्य",
