  "visionTitle": "हमारा नज़रिया",
  "visionDesc": "जैविक कृषि में एक विश्वसनीय वैश्विक भागीदार बनना, किसानों को भावी पीढ़ियों के लिए जैविक मिट्टी कायाकल्प और रसायन-अवशेष-मुक्त फसलों की ओर ले जाना।",
  "commitmentTitle": "हमारी प्रतिबद्धता",
  "commitmentDesc": "हम किसानों के साथ खड़े हैं, उन्हें तकनीकी मार्गदर्शन, जिम्मेदार निर्देश और मिट्टी की स्थिति और फसल चक्र के लिए तैयार प्रीमियम जैविक समाधान प्रदान करते हैं।",
