    "a1": "जैव खतांमध्ये फायदेशीर सूक्ष्मजीवांच्या जिवंत पेशी असतात. बियाणे किंवा मातीवर लागू केल्यावर, ते रायझोस्फियरमध्ये वसाहत करतात आणि नायट्रोजन निश्चित करून, फॉस्फेट विरघळवून आणि पोटॅश एकत्र करून वनस्पतींना पोषक तत्त्वे उपलब्ध करून देतात.",
