    "overviewTitle": "आमचा प्रवास",
    "overviewDesc1": "BHARTI GREEN TECH ची स्थापना सातारा, महाराष्ट्र येथे एकच दृष्टी घेऊन करण्यात आली: भारतीय शेतकऱ्यांसाठी मातीचा रासायनिक ऱ्हास आणि वाढत्या निविष्ठा खर्चाच्या दुहेरी आव्हानांचे निराकरण करण्यासाठी. आम्ही ओळखले की शाश्वत भविष्याचा मार्ग आमच्या शेतजमिनींचे जैविक आरोग्य पुनर्संचयित करण्यात आहे.",
