  "aboutUsHeading": "आमच्या कंपनीबद्दल",
  "companyOverviewTag": "विहंगावलोकन",
  "companyOverviewTitle": "जैवतंत्रज्ञान आणि कृषी ब्रिजिंग",
  "aboutText1": "BHARTI GREEN TECH ही एक भारतीय कृषी जैवतंत्रज्ञान कंपनी आहे जी संशोधन-समर्थित, उच्च-कार्यक्षमतेचे पीक खाद्य आणि जैविक संरक्षण उपाय तयार करण्यासाठी समर्पित आहे. नवी मुंबईतील आमच्या नोंदणीकृत कार्यालयातून आणि सातारा, महाराष्ट्रातील उत्पादन युनिटमधून, आम्ही जैविक उपाय तयार करतो जे माती समृद्ध करतात, बियाणे उत्तेजित करतात आणि बुरशीजन्य किंवा कीटकांच्या तणावाविरूद्ध झाडाची पाने मजबूत करतात.",
  "aboutText2": "आम्ही शेतकरी-प्रथम तत्त्वज्ञानाने कार्य करतो. कालांतराने मातीतील कार्बनचे नुकसान करणाऱ्या जेनेरिक रसायनांवर अवलंबून राहण्याऐवजी, आमची प्रयोगशाळा प्रक्रिया विशिष्ट सूक्ष्मजीवांना वेगळे करते, ज्यामध्ये नायट्रोजन-फिक्सर, फॉस्फेट विद्राव्य आणि एन्टोमोपॅथोजेनिक बुरशी यांचा समावेश होतो. हे पाण्यात विरघळणारे डेक्सट्रोज वाहक पावडर, स्थिर द्रव कंसोर्टिया आणि विविध पिकांच्या गरजांसाठी स्लो-रिलीझ ग्रॅन्युलमध्ये परिष्कृत केले जातात.",
